import {svg,bounds,scale,axes,text,esc} from '../gallery-utils.js';
import {plotTheme} from '../figure-themes.js';
export function distribution(values,bins){if(!Number.isInteger(+bins))throw Error('分箱数必须为整数');let lo=Math.min(...values),hi=Math.max(...values);if(lo===hi){lo-=.5;hi+=.5;}const step=(hi-lo)/bins,counts=Array(+bins).fill(0);values.forEach(v=>counts[Math.min(bins-1,Math.floor((v-lo)/step))]++);return {lo,hi,step,counts};}
export function render({data,params:p}){const values=data.map(d=>d.value).sort((a,b)=>a-b),dist=distribution(values,+p.bins),b=bounds(p),x=scale([dist.lo,dist.hi],b.l,b.r),y=scale([0,Math.max(...dist.counts)],b.b,b.t),z=scale([0,100],b.b,b.t);let s=axes(b,x,y,{...p,yLabel:'频数'});dist.counts.forEach((n,i)=>s+=`<rect x="${x(dist.lo+i*dist.step)+1}" y="${y(n)}" width="${(b.r-b.l)/p.bins-2}" height="${b.b-y(n)}" fill="${esc(p.color)}" fill-opacity="0.65"/>`);if(p.cdf==='显示'){const curve=plotTheme(p)?.series[1]??'#b95148';let points=`${b.l},${b.b} `,prev=0;values.forEach((v,i)=>{points+=`${x(v)},${z(prev)} ${x(v)},${z((i+1)/values.length*100)} `;prev=(i+1)/values.length*100;});points+=`${b.r},${b.t}`;s+=`<polyline points="${points}" fill="none" stroke="${curve}" stroke-width="2"/><path d="M${b.r},${b.t}V${b.b}" stroke="${curve}"/>`;for(const v of z.ticks)s+=text(b.r+8,z(v)+4,v+'%');s+=text(b.r+8,b.t-15,'累计比例');}return svg(p,s);}